def cargar(apps, schema_editor):
    Municipio = apps.get_model(APP, "Municipio")
    TipoBanco = apps.get_model(APP, "TipoBanco")
    Proyecto = apps.get_model(APP, "ProgramacionProyectos")
    Programacion = apps.get_model(APP, "ProgramacionMeta")
    Observacion = apps.get_model(APP, "ObservacionProyecto")
    Meta = apps.get_model(APP, "MetaIndicador")

    municipios = {n: Municipio.objects.get_or_create(nombre=n)[0] for n in MUNICIPIOS}
    bancos = {}
    for _, _, _, banco, _, _ in PROYECTOS:
        if banco and banco not in bancos:
            bancos[banco] = TipoBanco.objects.get_or_create(nombre=banco)[0]
    metas = {m.codigo: m for m in Meta.objects.all()}

    proyectos = {}
    for n, bpin, nombre, banco, vigencias, nombres_municipios in PROYECTOS:
        proyecto = Proyecto.objects.create(bpin=bpin, nombre=nombre, vigencias=vigencias,
                                           tipo_banco=bancos.get(banco))
        proyecto.municipios.set([municipios[m] for m in nombres_municipios])
        proyectos[n] = proyecto

    nuevas, sin_meta = [], []
    for id_access, n, codigo, vigencia, valor in PROGRAMACIONES:
        if codigo not in metas:
            sin_meta.append((n, codigo, vigencia, valor))
            continue
        nuevas.append(Programacion(id_access=id_access, proyecto=proyectos[n], meta=metas[codigo],
                                   vigencia=vigencia,
                                   meta_vigencia=Decimal(valor) if valor is not None else None))
    Programacion.objects.bulk_create(nuevas, batch_size=500)

    notas = [Observacion(proyecto=proyectos[n], fecha=None, texto=texto) for n, texto in OBSERVACIONES]
    notas += [Observacion(proyecto=proyectos[n], fecha=None,
                          texto=f"Programado en {codigo}, {vigencia or 'sin vigencia'}, con meta "
                                f"{valor if valor is not None else 'sin dato'}: esa meta no esta en el "
                                f"catalogo del plan")
              for n, codigo, vigencia, valor in sin_meta]
    Observacion.objects.bulk_create(notas, batch_size=500)
    if sin_meta:
        print(f"\n  Programaciones sin meta en el catalogo ({len(sin_meta)}): "
              + ", ".join(sorted({c for _, c, _, _ in sin_meta})))


def descargar(apps, schema_editor):
    # Solo lo que cargo esta migracion. Los catalogos se dejan si algo mas los usa.
    Proyecto = apps.get_model(APP, "ProgramacionProyectos")
    for _, bpin, nombre, _, _, _ in PROYECTOS:
        Proyecto.objects.filter(bpin=bpin, nombre=nombre).delete()
    apps.get_model(APP, "TipoBanco").objects.filter(proyectos__isnull=True).delete()
    apps.get_model(APP, "Municipio").objects.filter(nombre__in=MUNICIPIOS, proyectos__isnull=True).delete()


class Migration(migrations.Migration):

    dependencies = [
        (APP, "0013_programacion_de_proyectos"),
    ]

    operations = [
        migrations.RunPython(cargar, descargar),
    ]
